--- a/csv.test.ts	2026-10-24 02:28:11
+++ b/csv.test.ts	2026-10-24 02:29:51
@@ -23,3 +23,94 @@
   expect(s.push("d")).toEqual([]);
   expect(s.end()).toEqual([["c", "d"]]);
 });
+
+function streamAll(chunks: string[]): string[][] {
+  const s = new CsvStream();
+  const rows: string[][] = [];
+  for (const chunk of chunks) rows.push(...s.push(chunk));
+  rows.push(...s.end());
+  return rows;
+}
+
+// The rows from parseCsv, or "SyntaxError" when it rejects the input.
+function parseOutcome(input: string): string[][] | "SyntaxError" {
+  try {
+    return parseCsv(input);
+  } catch (e) {
+    if (e instanceof SyntaxError) return "SyntaxError";
+    throw e;
+  }
+}
+
+function streamOutcome(chunks: string[]): string[][] | "SyntaxError" {
+  try {
+    return streamAll(chunks);
+  } catch (e) {
+    if (e instanceof SyntaxError) return "SyntaxError";
+    throw e;
+  }
+}
+
+const streamInputs = [
+  "",
+  "\uFEFF",
+  "\uFEFF\uFEFF",
+  "\uFEFFa",
+  "a\n",
+  "\n",
+  "a\n\nb",
+  "a,",
+  ",",
+  "a,\n",
+  "a\rb",
+  "a\r",
+  "a\r\r\n",
+  "a\r,b",
+  '""',
+  '"a""b"',
+  '"a"',
+  '"a"\r\n',
+  '"a",x',
+  'a"b',
+  '"a"b',
+  '"abc',
+  '"a"\rx',
+  '"a"\r',
+  'a,b\r\n"x,""y""",z\n',
+  'a,"b\r\nc",d\n',
+];
+
+test("any split of the input gives the rows parseCsv gives", () => {
+  for (const input of streamInputs) {
+    const expected = parseOutcome(input);
+    const n = input.length;
+    for (let i = 0; i <= n; i++) {
+      expect(streamOutcome([input.slice(0, i), input.slice(i)])).toEqual(expected);
+      for (let j = i; j <= n; j++) {
+        expect(streamOutcome([input.slice(0, i), input.slice(i, j), input.slice(j)])).toEqual(expected);
+      }
+    }
+    expect(streamOutcome(input.split(""))).toEqual(expected);
+    expect(streamOutcome(["", ...input.split("").flatMap((c) => [c, ""])])).toEqual(expected);
+  }
+});
+
+test("a row is returned as soon as its row end arrives", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb")).toEqual([["a"]]);
+  expect(s.push("\n")).toEqual([["b"]]);
+  expect(s.push('"x"')).toEqual([]);
+  expect(s.push("\n")).toEqual([["x"]]);
+  expect(s.end()).toEqual([]);
+});
+
+test("a long input in small chunks is parsed in linear time", () => {
+  const input = '"' + "x,\n".repeat(700_000) + '"\n' + "a,b\r\n".repeat(200_000) + "end";
+  const chunks: string[] = [];
+  for (let i = 0, size = 1; i < input.length; size = (size % 7) + 1) {
+    chunks.push(input.slice(i, i + size));
+    i += size;
+  }
+  expect(streamAll(chunks)).toEqual(parseCsv(input));
+});
diff -ruN --exclude=node_modules --exclude=.git a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-24 02:28:11
+++ b/csv.ts	2026-10-24 02:29:28
@@ -50,3 +50,104 @@
   rows.push(row);
   return rows;
 }
+
+type CsvState = "fieldStart" | "unquoted" | "unquotedCr" | "quoted" | "quoteSeen" | "afterQuoteCr";
+
+/**
+ * The same CSV as `parseCsv`, fed in chunks. Each call returns the rows that are complete by then. The work for a
+ * chunk depends only on the chunk and on the current field and row, never on the input before them.
+ */
+export class CsvStream {
+  private state: CsvState = "fieldStart";
+  private field = "";
+  private row: string[] = [];
+  private started = false;
+
+  push(chunk: string): string[][] {
+    const rows: string[][] = [];
+    for (const c of chunk) {
+      if (!this.started) {
+        this.started = true;
+        if (c === "\uFEFF") continue;
+      }
+      this.feed(c, rows);
+    }
+    return rows;
+  }
+
+  end(): string[][] {
+    if (this.state === "quoted") throw new SyntaxError("a quoted field is still open at the end of the input");
+    if (this.state === "afterQuoteCr") throw new SyntaxError("a \\r after a closing quote must be followed by \\n");
+    if (this.state === "fieldStart" && this.row.length === 0) return [];
+    if (this.state === "unquotedCr") this.field += "\r";
+    this.pushField();
+    return [this.finishRow()];
+  }
+
+  private feed(c: string, rows: string[][]): void {
+    switch (this.state) {
+      case "fieldStart":
+        if (c === '"') this.state = "quoted";
+        else {
+          this.state = "unquoted";
+          this.feed(c, rows);
+        }
+        return;
+      case "unquoted":
+        if (c === ",") {
+          this.pushField();
+          this.state = "fieldStart";
+        } else if (c === "\n") {
+          this.pushField();
+          rows.push(this.finishRow());
+        } else if (c === "\r") this.state = "unquotedCr";
+        else if (c === '"') throw new SyntaxError("a quote in a field that is not quoted");
+        else this.field += c;
+        return;
+      case "unquotedCr":
+        if (c === "\n") {
+          this.pushField();
+          rows.push(this.finishRow());
+        } else {
+          this.field += "\r";
+          this.state = "unquoted";
+          this.feed(c, rows);
+        }
+        return;
+      case "quoted":
+        if (c === '"') this.state = "quoteSeen";
+        else this.field += c;
+        return;
+      case "quoteSeen":
+        if (c === '"') {
+          this.field += '"';
+          this.state = "quoted";
+        } else if (c === ",") {
+          this.pushField();
+          this.state = "fieldStart";
+        } else if (c === "\n") {
+          this.pushField();
+          rows.push(this.finishRow());
+        } else if (c === "\r") this.state = "afterQuoteCr";
+        else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote`);
+        return;
+      case "afterQuoteCr":
+        if (c !== "\n") throw new SyntaxError("a \\r after a closing quote must be followed by \\n");
+        this.pushField();
+        rows.push(this.finishRow());
+        return;
+    }
+  }
+
+  private pushField(): void {
+    this.row.push(this.field);
+    this.field = "";
+  }
+
+  private finishRow(): string[] {
+    const row = this.row;
+    this.row = [];
+    this.state = "fieldStart";
+    return row;
+  }
+}

diff -ruN --exclude=node_modules --exclude=.git a/deny.extra.test.ts b/deny.extra.test.ts
--- a/deny.extra.test.ts	1970-01-01 07:00:00
