@@ -0,0 +1,59 @@
+import { expect, test } from 'bun:test';
+import { denyListed } from './deny.ts';
+
+const cwd = '/work/repo';
+const name = (argv: string[]) => denyListed(argv, cwd)?.name;
+
+test('abbreviated long options are matched', () => {
+  expect(name(['git', 'push', '--mirr'])).toBe('force-push');
+  expect(name(['git', 'push', 'origin', '--del', 'old'])).toBe('force-push');
+  expect(name(['git', 'push', '--pru', 'origin'])).toBe('force-push');
+  expect(name(['git', 'reset', '--har', 'HEAD~1'])).toBe('reset-hard');
+  expect(name(['git', 'clean', '--forc'])).toBe('clean-force');
+  expect(name(['rm', '--recur', '/etc'])).toBe('rm-outside');
+});
+
+test('command names are case-insensitive (APFS)', () => {
+  expect(name(['RM', '-rf', '/'])).toBe('rm-outside');
+  expect(name(['GIT', 'push', '-f'])).toBe('force-push');
+});
+
+test('find skips options before the start paths', () => {
+  expect(name(['find', '-L', '/', '-delete'])).toBe('rm-outside');
+  expect(name(['find', '-H', '-O3', '-D', 'search', '/', '-delete'])).toBe('rm-outside');
+});
+
+test('push option values are not refspecs', () => {
+  expect(denyListed(['git', 'push', '-o', '+x', 'origin', 'main'], cwd)).toBeUndefined();
+});
+
+test('backtick command substitution is unresolvable', () => {
+  expect(name(['rm', '-rf', '`echo /`'])).toBe('rm-outside');
+});
+
+test('force-push reason names the matched word', () => {
+  expect(denyListed(['git', 'push', '-f'], cwd)?.reason).toContain('-f');
+});
+
+test('git clean with --force after -n still counts as dry run', () => {
+  expect(name(['git', 'clean', '--force', '-n'])).toBeUndefined();
+});
+
+test('git global options --work-tree and --namespace take a value', () => {
+  expect(name(['git', '--work-tree', 'w', 'push', '-f'])).toBe('force-push');
+  expect(name(['git', '--namespace', 'n', 'push', '-f'])).toBe('force-push');
+  expect(name(['git', '--work-tree', 'w', 'status'])).toBeUndefined();
+});
+
+test('--git-dir=x as one word', () => {
+  expect(name(['git', '--git-dir=.git', 'push', '-f'])).toBe('force-push');
+});
+
+test('find with ~user or cwd-absolute start path', () => {
+  expect(name(['find', '~bob', '-delete'])).toBe('rm-outside');
+  expect(name(['find', '/work/repo/src', '-delete'])).toBeUndefined();
+});
+
+test('rm -r with a $ target after --', () => {
+  expect(name(['rm', '-r', '--', '$DIR'])).toBe('rm-outside');
+});
