+++ b/deny.ts	2026-10-24 02:30:56
@@ -14,6 +14,12 @@
 // Same directory as cwd, e.g. `.`, `./`, or cwd's absolute path.
 export const sameDir = (path: string, cwd: string) => relative(resolve(cwd), resolve(cwd, expandHome(path))) === '';

+const base = (w: string) => w.split('/').pop() ?? '';
+const shortGroup = (w: string) => w.length > 1 && w[0] === '-' && w[1] !== '-';
+const unresolvable = (p: string) => p.includes('$') || p.includes('`') || (p.startsWith('~') && p !== '~' && !p.startsWith('~/'));
+// A long option, or a unique-enough prefix of one (git and GNU rm accept abbreviations).
+const longIs = (w: string, full: string) => w.startsWith('--') && w.split('=')[0].length >= 5 && full.startsWith(w.split('=')[0]);
+
 // Looks at one simple command's argv (already split, quotes removed) and returns a Hit when it must be denied.
 //
 // git (argv[0] may be a path such as /usr/bin/git). Global options before the subcommand are skipped; -C, -c,
@@ -36,5 +42,67 @@
 //
 // Anything else: undefined.
 export function denyListed(argv: string[], cwd: string): Hit | undefined {
-  throw new Error('not implemented');
+  if (argv.length === 0) return undefined;
+  const cmd = base(argv[0]).toLowerCase();
+
+  if (cmd === 'git') {
+    let i = 1;
+    while (argv[i]?.startsWith('-')) {
+      i += ['-C', '-c', '--git-dir', '--work-tree', '--namespace'].includes(argv[i]) ? 2 : 1;
+    }
+    const sub = argv[i];
+    const rest = argv.slice(i + 1);
+
+    if (sub === 'push') {
+      for (let j = 0; j < rest.length; j++) {
+        const w = rest[j];
+        if (['-o', '--push-option', '--repo', '--receive-pack', '--exec'].includes(w)) {
+          j++;
+          continue;
+        }
+        const forced =
+          ['--force', '--force-with-lease', '--mirror', '--delete', '--prune'].some((f) => longIs(w, f)) ||
+          (shortGroup(w) && /[fd]/.test(w)) ||
+          (!w.startsWith('-') && /^[+:]/.test(w));
+        if (forced) return { name: 'force-push', reason: `git push ${w} rewrites remote history` };
+      }
+    }
+
+    if (sub === 'reset' && rest.some((w) => longIs(w, '--hard'))) return { name: 'reset-hard', reason: 'git reset --hard discards work' };
+
+    if (sub === 'clean') {
+      const forced = rest.some((w) => longIs(w, '--force') || (shortGroup(w) && w.includes('f')));
+      const dryRun = rest.includes('-n') || rest.includes('--dry-run');
+      if (forced && !dryRun) return { name: 'clean-force', reason: 'git clean -f deletes untracked files' };
+    }
+    return undefined;
+  }
+
+  if (cmd === 'rm') {
+    const args = argv.slice(1);
+    const end = args.indexOf('--');
+    const flags = end === -1 ? args : args.slice(0, end);
+    const targets = [...flags.filter((w) => !w.startsWith('-')), ...(end === -1 ? [] : args.slice(end + 1))];
+    const recursive = flags.some((w) => longIs(w, '--recursive') || (shortGroup(w) && /[rR]/.test(w)));
+    if (!recursive) return undefined;
+    if (targets.length === 0) return { name: 'rm-outside', reason: 'rm -r with no targets' };
+    const bad = targets.find((t) => unresolvable(t) || !insideWorkspace(t, cwd) || sameDir(t, cwd));
+    if (bad !== undefined) return { name: 'rm-outside', reason: `rm -r of ${bad} is outside the working directory` };
+    return undefined;
+  }
+
+  if (cmd === 'find') {
+    if (!argv.slice(1).some((w) => ['-delete', '-exec', '-execdir'].includes(w))) return undefined;
+    let i = 1;
+    while (/^-[HLP]$|^-O\d+$/.test(argv[i] ?? '')) i++;
+    if (argv[i] === '-D') i += 2;
+    const starts: string[] = [];
+    for (; i < argv.length && !argv[i].startsWith('-'); i++) starts.push(argv[i]);
+    if (starts.length === 0) starts.push('.');
+    const bad = starts.find((p) => unresolvable(p) || !insideWorkspace(p, cwd));
+    if (bad !== undefined) return { name: 'rm-outside', reason: `find ${bad} acts outside the working directory` };
+    return undefined;
+  }
+
+  return undefined;
 }

diff -ruN --exclude=node_modules --exclude=.git a/edit.review.test.ts b/edit.review.test.ts
--- a/edit.review.test.ts	1970-01-01 07:00:00
+++ b/edit.review.test.ts	2026-10-24 02:33:36
@@ -0,0 +1,51 @@
+import { describe, expect, test } from 'bun:test';
+import { applyEdit } from './edit.ts';
+
+const ok = (r: ReturnType<typeof applyEdit>) => {
+  if ('error' in r) throw new Error(r.error);
+  return r;
+};
+const err = (r: ReturnType<typeof applyEdit>) => ('error' in r ? r.error : '');
+
+describe('review: overlapping and replace_all', () => {
+  test('overlapping exact matches are ambiguous', () => {
+    expect(err(applyEdit('}\n}\n}\n', { old_text: '}\n}', new_text: 'X' }))).toContain('matches 2 places');
+  });
+  test('replace_all span runs from first match to end of last', () => {
+    const r = ok(applyEdit('x\ny\nx\nz\nx\n', { old_text: 'x', new_text: 'w', replace_all: true }));
+    expect(r.applied).toEqual({ from: 1, to: 5, tier: 'exact', count: 3 });
+    expect(r.content).toBe('w\ny\nw\nz\nw\n');
+  });
+  test('ambiguity error pins the exact line number', () => {
+    const src = Array.from({ length: 9 }, () => 'a').join('\n') + '\nx\nx\n';
+    expect(err(applyEdit(src, { old_text: 'x', new_text: 'z' }))).toContain('first at line 10');
+  });
+});
+
+describe('review: indentation', () => {
+  test('lines left of the first line are dedented relative to it', () => {
+    const r = ok(applyEdit('f() {\n    if (a) {\n        return 1;\n    }\n}\n', { old_text: '    return 1;\n}', new_text: '    return 2;\n}' }));
+    expect(r.content).toBe('f() {\n    if (a) {\n        return 2;\n    }\n}\n');
+  });
+  test('two windows match in the indentation tier: error', () => {
+    const r = applyEdit('  a\n  b\nc\n    a\n    b\n', { old_text: 'a\nb', new_text: 'x' });
+    expect(err(r)).toContain('matches 2 places');
+    expect(err(r)).toContain('lines 1, 4');
+  });
+});
+
+describe('review: CRLF', () => {
+  test('replacement keeps CRLF line endings', () => {
+    const r = ok(applyEdit('a\r\nb\r\nc\r\n', { old_text: 'a\nb', new_text: 'A\nB' }));
+    expect(r.content).toBe('A\r\nB\r\nc\r\n');
+  });
+});
+
+describe('review: not-found pointer', () => {
+  test('lists at most 5 lines', () => {
+    const src = Array.from({ length: 7 }, () => 'foo').join('\n') + '\n';
+    expect(err(applyEdit(src, { old_text: 'foo\nbar', new_text: 'x' }))).toBe(
+      'old_text not found; first line appears at line 1, 2, 3, 4, 5',
+    );
+  });
+});
diff -ruN --exclude=node_modules --exclude=.git a/edit.ts b/edit.ts
--- a/edit.ts	2026-10-24 02:30:59
+++ b/edit.ts	2026-10-24 02:33:25
@@ -23,5 +23,81 @@
 // - nothing matched: message contains "not found", and when the first non-blank line of old_text (trimmed) occurs
 //   in some lines of content, "first line appears at line L1, L2" (at most 5 lines).
 export function applyEdit(content: string, edit: TextEdit): { content: string; applied: Applied } | { error: string } {
-  throw new Error('not implemented');
+  const { old_text: old, new_text: neu, replace_all } = edit;
+  if (old === '') return { error: 'old_text is empty; use write to create or overwrite a file' };
+  if (old === neu) return { error: 'old_text and new_text are the same; nothing to change' };
+
+  const stripNL = (s: string) => (s.endsWith('\n') ? s.slice(0, -1) : s);
+  const countNL = (s: string) => s.split('\n').length - 1;
+  const lineAt = (idx: number) => 1 + countNL(content.slice(0, idx));
+
+  const starts: number[] = [];
+  for (let i = content.indexOf(old); i !== -1; i = content.indexOf(old, i + 1)) starts.push(i);
+  if (starts.length === 1) {
+    const i = starts[0];
+    const from = lineAt(i);
+    const to = from + countNL(stripNL(old));
+    return { content: content.slice(0, i) + neu + content.slice(i + old.length), applied: { from, to, tier: 'exact', count: 1 } };
+  }
+  if (starts.length > 1) {
+    if (!replace_all) return { error: `old_text matches ${starts.length} places (first at line ${lineAt(starts[0])}); add more context or set replace_all` };
+    const from = lineAt(starts[0]);
+    const to = lineAt(starts[starts.length - 1]) + countNL(stripNL(old));
+    const count = content.split(old).length - 1;
+    return { content: content.split(old).join(neu), applied: { from, to, tier: 'exact', count } };
+  }
+
+  const endsNL = content.endsWith('\n');
+  const lines = content.split('\n');
+  if (endsNL) lines.pop();
+  const oldLines = stripNL(old).split('\n');
+  const newLines = stripNL(neu) === '' ? [] : stripNL(neu).split('\n');
+
+  const findWindows = (norm: (l: string) => string) => {
+    const out: number[] = [];
+    for (let s = 0; s + oldLines.length <= lines.length; s++) {
+      if (oldLines.every((o, k) => norm(lines[s + k]) === norm(o))) out.push(s);
+    }
+    return out;
+  };
+  // Lines are split on '\n', so a CRLF file keeps its '\r' on untouched lines; give replacement lines the same ending.
+  const cr = content.includes('\r\n') ? '\r' : '';
+  const replaceWindow = (s: number, replacement: string[]) => {
+    const next = lines.slice();
+    next.splice(s, oldLines.length, ...replacement.map((l) => (cr ? l.replace(/\r$/, '') + cr : l)));
+    return next.join('\n') + (endsNL ? '\n' : '');
+  };
+  const indentOf = (l: string) => /^\s*/.exec(l)![0];
+  const firstNonBlank = (ls: string[]) => ls.find((l) => l.trim() !== '') ?? '';
+  const reindent = (s: number) => {
+    const oldIndent = indentOf(firstNonBlank(oldLines));
+    const fileIndent = indentOf(firstNonBlank(lines.slice(s, s + oldLines.length)));
+    return newLines.map((l) => {
+      if (l.trim() === '') return '';
+      if (l.startsWith(oldIndent)) return fileIndent + l.slice(oldIndent.length);
+      const short = oldIndent.length - indentOf(l).length;
+      if (short > 0) return fileIndent.slice(0, Math.max(0, fileIndent.length - short)) + l.trimStart();
+      return fileIndent + l.trimStart();
+    });
+  };
+
+  const tiers: [Tier, (l: string) => string][] = [
+    ['trailing-space', (l) => l.trimEnd()],
+    ['indentation', (l) => l.trim()],
+  ];
+  for (const [tier, norm] of tiers) {
+    const hits = findWindows(norm);
+    if (hits.length === 0) continue;
+    if (hits.length > 1) return { error: `old_text matches ${hits.length} places (lines ${hits.map((s) => s + 1).join(', ')}); add more context` };
+    const s = hits[0];
+    const replacement = tier === 'indentation' ? reindent(s) : newLines;
+    return { content: replaceWindow(s, replacement), applied: { from: s + 1, to: s + oldLines.length, tier, count: 1 } };
+  }
+
+  const first = firstNonBlank(old.split('\n')).trim();
+  const found: number[] = [];
+  if (first !== '') {
+    for (let i = 0; i < lines.length && found.length < 5; i++) if (lines[i].includes(first)) found.push(i + 1);
+  }
+  return { error: `old_text not found${found.length ? `; first line appears at line ${found.join(', ')}` : ''}` };
 }

