+// Slop checks over a set of file changes: test tampering and silenced or stubbed code.
+// Pure: callers supply the changes (from a git patch or from session events).
+
+import { relative, resolve } from 'node:path';
+import type { SessionEvent } from '../types.ts';
+
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+
+export type SlopRule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+
+export type SlopFinding = { rule: SlopRule; path: string; line?: string };
+
+export const flagOf = (f: SlopFinding): string => `${f.rule} ${f.path}${f.line === undefined ? '' : `: ${f.line}`}`;
+
+const TEST_PATH = /(^|\/)(tests?|__tests__|spec)\/|\.(test|spec)\.[cm]?[jt]sx?$|_test\.(go|py)$|(^|\/)test_[^/]*\.py$/;
+const CODE_EXT = /\.(ts|tsx|mts|cts|js|jsx|mjs|cjs|py|go|rs|java|kt|rb|php|cs|swift|c|cc|cpp|h|hpp|scala)$/;
+const TYPE_EXT = /\.(ts|tsx|mts|cts)$/;
+
+const ASSERTION = /\b(assert\w*|expect)\s*\(|^\s*assert\b|\bt\.(Error|Fatal)\w*\(/;
+const SKIP = /\b(it|test|describe)\.(skip|todo)\b|\bx(it|describe|test)\(|\bt\.Skip(Now)?\(|@pytest\.mark\.skip|\bpytest\.skip\(|@unittest\.skip|#\[ignore\]/;
+const SUPPRESSION = /@ts-(ignore|nocheck|expect-error)|eslint-disable|biome-ignore|#\s*type:\s*ignore|#\s*noqa\b|#\s*pylint:\s*disable|\/\/\s*nolint\b|#!?\[allow\(|@SuppressWarnings/;
+const SWALLOWED =
+  /catch\s*(\([^)]*\))?\s*\{\s*\}|\bexcept\b[^:]*:\s*(pass|\.\.\.)\s*$|\.catch\(\s*\(\s*\w*\s*\)\s*=>\s*(\{\s*\}|undefined|null)\s*\)/;
+const TYPE_ESCAPE = /\bas\s+any\b(?!\s+\w)|\bas\s+unknown\s+as\b/;
+const STUB = /\b(throw|raise|panic)\b.*not[ _-]?implemented/i;
+const STUB_TYPES = /\bNotImplementedError\b|\b(todo|unimplemented)!\(/;
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  for (const c of changes) {
+    const isTest = TEST_PATH.test(c.path);
+    if (isTest && c.deleted) {
+      out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (isTest) {
+      const removed = c.removed.filter((l) => ASSERTION.test(l)).length;
+      const added = c.added.filter((l) => ASSERTION.test(l)).length;
+      if (removed > added) out.push({ rule: 'test-weakened', path: c.path, line: `${removed - added} assertions removed` });
+    }
+    if (!CODE_EXT.test(c.path)) continue;
+    for (let i = 0; i < c.added.length; i++) {
+      const raw = c.added[i]!;
+      const line = raw.trim().slice(0, 80);
+      // An opener and its empty body can sit on two adjacent added lines (`except E:` then `pass`).
+      const next = c.added[i + 1];
+      const rule = firstRule(raw, isTest, TYPE_EXT.test(c.path)) ?? (next !== undefined && SWALLOWED.test(`${raw}\n${next}`) ? 'swallowed-error' : undefined);
+      if (rule) out.push({ rule, path: c.path, line });
+    }
+  }
+  return out;
+}
+
+function firstRule(text: string, isTest: boolean, isTypeFile: boolean): SlopRule | undefined {
+  if (isTest && SKIP.test(text)) return 'test-skipped';
+  if (SUPPRESSION.test(text)) return 'suppression';
+  if (SWALLOWED.test(text)) return 'swallowed-error';
+  if (isTypeFile && TYPE_ESCAPE.test(text)) return 'type-escape';
+  if (STUB.test(text) || STUB_TYPES.test(text)) return 'stub';
+  return undefined;
+}
+
+// Parses `git diff -U0` output. Header lines before the first hunk are skipped; inside a hunk, +/- lines count.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  let oldPath = '';
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/(.*) b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[2]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+      oldPath = head[1]!;
+      continue;
+    }
+    if (!cur) continue;
+    if (line.startsWith('@@')) {
+      inHunk = true;
+    } else if (line.startsWith('deleted file mode')) {
+      cur.deleted = true;
+      cur.path = oldPath; // a deleted file keeps its old name
+    } else if (inHunk && line.startsWith('+')) {
+      cur.added.push(line.slice(1));
+    } else if (inHunk && line.startsWith('-')) {
+      cur.removed.push(line.slice(1));
+    }
+  }
+  return out;
+}
+
+export function changesFromCalls(events: SessionEvent[], cwd: string): FileChange[] {
+  const intents = new Map<string, Extract<SessionEvent, { kind: 'tool_intent' }>>();
+  const completed = new Set<string>();
+  for (const e of events) {
+    if (e.kind === 'tool_intent' && (e.tool === 'edit' || e.tool === 'write')) intents.set(e.callId, e);
+    if (e.kind === 'tool_result' && e.status === 'completed') completed.add(e.callId);
+  }
+  const out: FileChange[] = [];
+  // Per file, the added lines still in its latest state: a write replaces them, an edit's old_text removes them.
+  const live = new Map<string, Map<string, number>>();
+  const count = (state: Map<string, number>, l: string) => state.set(l, (state.get(l) ?? 0) + 1);
+  for (const [callId, intent] of intents) {
+    if (!completed.has(callId)) continue;
+    const input = intent.input;
+    const path = relative(cwd, resolve(cwd, String(input.path)));
+    const state = live.get(path) ?? new Map<string, number>();
+    live.set(path, state);
+    if (intent.tool === 'write') {
+      // The old content is unknown, so removed stays empty: without snapshots a write never shows test-weakened.
+      const added = splitLines(String(input.content));
+      state.clear();
+      added.forEach((l) => count(state, l));
+      out.push({ path, added, removed: [], deleted: false });
+    } else {
+      const edits = (input.edits as { old_text: string; new_text: string }[]) ?? [];
+      const added = edits.flatMap((x) => splitLines(x.new_text));
+      const removed = edits.flatMap((x) => splitLines(x.old_text));
+      for (const l of removed) {
+        const n = state.get(l) ?? 0;
+        if (n > 1) state.set(l, n - 1);
+        else state.delete(l);
+      }
+      added.forEach((l) => count(state, l));
+      out.push({ path, added, removed, deleted: false });
+    }
+  }
+  // A line the run later removed or overwrote is no longer a finding: keep only the added lines still present.
+  for (const c of out) {
+    const state = live.get(c.path)!;
+    c.added = c.added.filter((l) => {
+      const n = state.get(l) ?? 0;
+      if (n === 0) return false;
+      state.set(l, n - 1);
+      return true;
+    });
+  }
+  return out;
+}
+
+function splitLines(s: string): string[] {
+  const lines = s.split('\n');
+  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
+  return lines;
+}
