+  test('"as any" in prose is not a type escape, a real cast is', () => {
+    expect(findSlop([change('a.ts', ['// treat it as any other value'])])).toEqual([]);
+    expect(findSlop([change('a.ts', ['const x = y as any;'])])).toEqual([{ rule: 'type-escape', path: 'a.ts', line: 'const x = y as any;' }]);
+  });
+
+  test('a Makefile variable named test is not a test target', () => {
+    expect(detectChecks(dir({ Makefile: 'test := foo\nall:\n\techo\n' }))).toEqual([]);
