@@ -0,0 +1,57 @@
+import type { Evidence, ToolOutput } from '../types.ts';
+import type { ToolSpec } from './registry.ts';
+
+// A sub-thread: a fresh session with its own log, started by the writer. Only its report comes back.
+export type SpawnKind = 'explore' | 'work';
+
+export function spawnTool(run: (kind: SpawnKind, task: string, signal: AbortSignal) => Promise<ToolOutput>): ToolSpec {
+  return {
+    name: 'spawn',
+    description:
+      'Start a sub-thread with a fresh context for a self-contained piece of work. It sees only the task you write, so give it the full context. explore reads only and runs in parallel on a fast model; work may edit files and runs alone on your model, under the same policy and checks. Only its report comes back to you.',
+    schema: {
+      type: 'object',
+      properties: {
+        kind: { type: 'string', enum: ['explore', 'work'], description: 'explore: read-only; work: may edit' },
+        task: { type: 'string', description: 'The full task for the sub-thread' },
+      },
+      required: ['kind', 'task'],
+      additionalProperties: false,
+    },
+    effect: 'write_workspace',
+    effectOf: (i) => (i.kind === 'explore' ? 'read' : 'write_workspace'),
+    replay: 'unsafe',
+    async run(input, ctx) {
+      const kind = input.kind;
+      if (kind !== 'explore' && kind !== 'work') return { text: 'kind must be explore or work', isError: true };
+      const task = typeof input.task === 'string' ? input.task.trim() : '';
+      if (!task) return { text: 'task must not be empty', isError: true };
+      return run(kind, task, ctx.signal);
+    },
+  };
+}
+
+export function subPrompt(kind: SpawnKind, task: string): string {
+  const body =
+    kind === 'explore'
+      ? 'You are a sub-thread exploring for another session, which sees only your final reply. Read, change nothing, and report your findings with paths and line numbers.'
+      : 'You are a sub-thread doing a change for another session, which sees only your final reply. Do the change, run the declared checks, and end with a short report of what you changed and how you checked it.';
+  return `${task}\n\n${body}`;
+}
+
+export function subReport(r: {
+  id: string;
+  kind: SpawnKind;
+  model: string;
+  state: string;
+  result: string;
+  evidence?: Evidence;
+  subtype: string;
+}): string {
+  const lines = [`<sub-thread id="${r.id}" kind="${r.kind}" model="${r.model}" state="${r.state}">`, r.result, '</sub-thread>'];
+  if (r.evidence?.changed.length) lines.push(`Changed: ${r.evidence.changed.join(', ')}`);
+  const checks = r.evidence?.checks ?? [];
+  if (checks.length) lines.push(`Checks: ${checks.map((c) => `${c.command} (exit ${c.exitCode})`).join('; ')}`);
+  if (r.subtype !== 'success') lines.push(`The sub-thread ended with ${r.subtype} and stays listed; read it with read_thread ${r.id}.`);
+  return lines.join('\n');
+}
