+  const proc = Bun.spawnSync([BIN, 'threads', ...args, '--cwd', dir], { env: { ...process.env, CEDIA_HOME: join(dir, 'home') } });
+  return { code: proc.exitCode, out: proc.stdout.toString(), err: proc.stderr.toString() };
+};
