diff -ruN --exclude=node_modules --exclude=.git a/src/core/project/handoff.ts b/src/core/project/handoff.ts
--- a/src/core/project/handoff.ts	1970-01-01 07:00:00
+++ b/src/core/project/handoff.ts	2026-10-24 02:58:06
@@ -0,0 +1,16 @@
+import type { ModelSpec } from '../types.ts';
+
+// When a session's context passes its handoff point, cedia asks for a note and the next session goes on from it.
+export const HANDOFF_PROMPT =
+  'Your context is long, so this session ends now. A new session will go on with the task from a note you write now. ' +
+  'Reply with the note only, as text and with no tool calls: what is done, what was checked and how, what is left, ' +
+  'and the files and facts the next session needs. The task itself is passed on as written.';
+
+export const HANDOFF_NO_TOOLS = 'not run: this session is handing off; reply with the handoff note as text, with no tool calls.';
+
+export const HANDOFF_GO_ON = 'Go on with the task from where the handoff note leaves off. Look at the working tree before you trust the note.';
+
+// Half the window, at most 150k tokens, and never past the point where a long-context price starts.
+export function defaultHandoffAt(m: ModelSpec): number {
+  return Math.min(Math.floor(m.caps.contextWindow / 2), 150_000, m.price.above ? Math.floor(m.price.above.tokens * 0.9) : Infinity);
+}
diff -ruN --exclude=node_modules --exclude=.git a/src/core/project/threads.ts b/src/core/project/threads.ts
--- a/src/core/project/threads.ts	1970-01-01 07:00:00
+++ b/src/core/project/threads.ts	2026-10-24 03:06:01
@@ -0,0 +1,173 @@
+import { randomUUID } from 'node:crypto';
+import { appendFileSync, existsSync, mkdirSync, readdirSync, readFileSync } from 'node:fs';
+import { join } from 'node:path';
+
+// A thread is one piece of work in a project, kept as an append-only log per thread (<dir>/<id>.jsonl).
+export type ThreadState = 'working' | 'done' | 'stopped';
+
+export type ThreadEntry = (
+  | { kind: 'open'; task: string }
+  | { kind: 'session'; sessionId: string; model: string; role: string; why: 'start' | 'handoff' | 'resume' | 'fallback' }
+  | { kind: 'handoff'; sessionId: string; note: string }
+  | { kind: 'message'; id: string; from: string; text: string }
+  | { kind: 'delivered'; ids: string[]; sessionId: string }
+  | { kind: 'state'; state: ThreadState; result?: string; sessionId?: string }
+) & { at?: string };
+
+export type ThreadMessage = { id: string; from: string; text: string; at: string };
+
+export type Thread = {
+  id: string;
+  title: string;
+  task: string;
+  state: ThreadState;
+  result?: string;
+  handoff?: { sessionId: string; note: string; at: string };
+  latest?: { kind: 'handoff' | 'result'; sessionId: string; text: string };
+  sessions: { sessionId: string; model: string; role: string; why: string; at: string }[];
+  messages: ThreadMessage[];
+  pending: ThreadMessage[];
+  updatedAt: string;
+};
+
+const ID = /^t-[0-9a-f]{8}$/;
+
+export function titleOf(task: string): string {
+  const line = task.trim().split('\n')[0]!.trim();
+  return line.length > 60 ? `${line.slice(0, 57)}...` : line;
+}
+
+export function foldThread(id: string, entries: ThreadEntry[]): Thread {
+  const t: Thread = { id, task: '', title: '', state: 'working', sessions: [], messages: [], pending: [], updatedAt: '' };
+  const delivered = new Set<string>();
+  for (const e of entries) {
+    switch (e.kind) {
+      case 'open':
+        t.task = e.task;
+        t.title = titleOf(e.task);
+        break;
+      case 'session':
+        t.sessions.push({ sessionId: e.sessionId, model: e.model, role: e.role, why: e.why, at: e.at ?? '' });
+        t.state = 'working';
+        break;
+      case 'handoff':
+        t.handoff = { sessionId: e.sessionId, note: e.note, at: e.at ?? '' };
+        t.latest = { kind: 'handoff', sessionId: e.sessionId, text: e.note };
+        break;
+      case 'message':
+        t.messages.push({ id: e.id, from: e.from, text: e.text, at: e.at ?? '' });
+        break;
+      case 'delivered':
+        for (const mid of e.ids) delivered.add(mid);
+        break;
+      case 'state':
+        t.state = e.state;
+        t.result = e.result;
+        if (e.result !== undefined) {
+          t.latest = { kind: 'result', sessionId: e.sessionId ?? t.sessions.at(-1)?.sessionId ?? '', text: e.result };
+        }
+        break;
+    }
+  }
+  t.pending = t.messages.filter((m) => !delivered.has(m.id));
+  t.updatedAt = entries.at(-1)?.at ?? '';
+  return t;
+}
+
+export function threadsDir(home: string, slug: string): string {
+  return join(home, 'projects', slug, 'threads');
+}
+
+const line = (entry: ThreadEntry) => `${JSON.stringify({ ...entry, at: new Date().toISOString() })}\n`;
+
+export class ThreadStore {
+  private readonly dir: string;
+
+  constructor(dir: string) {
+    this.dir = dir;
+  }
+
+  private file(id: string): string {
+    return join(this.dir, `${id}.jsonl`);
+  }
+
+  private check(id: string): void {
+    if (!ID.test(id)) throw new Error(`not a thread id: ${id}`);
+    if (!existsSync(this.file(id))) throw new Error(`no thread ${id}`);
+  }
+
+  open(task: string): string {
+    mkdirSync(this.dir, { recursive: true });
+    const id = `t-${randomUUID().replace(/-/g, '').slice(0, 8)}`;
+    appendFileSync(this.file(id), line({ kind: 'open', task }));
+    return id;
+  }
+
+  has(id: string): boolean {
+    return ID.test(id) && existsSync(this.file(id));
+  }
+
+  read(id: string): Thread {
+    this.check(id);
+    const entries = readFileSync(this.file(id), 'utf8').split('\n').flatMap((l): ThreadEntry[] => {
+      if (!l.trim()) return [];
+      try {
+        return [JSON.parse(l) as ThreadEntry];
+      } catch {
+        return [];
+      }
+    });
+    return foldThread(id, entries);
+  }
+
+  append(id: string, entry: ThreadEntry): void {
+    this.check(id);
+    appendFileSync(this.file(id), line(entry));
+  }
+
+  send(id: string, from: string, text: string): string {
+    const mid = `m-${randomUUID().replace(/-/g, '').slice(0, 8)}`;
+    this.append(id, { kind: 'message', id: mid, from, text });
+    return mid;
+  }
+
+  list(): Thread[] {
+    if (!existsSync(this.dir)) return [];
+    return readdirSync(this.dir)
+      .filter((f) => f.endsWith('.jsonl') && ID.test(f.slice(0, -'.jsonl'.length)))
+      .map((f) => this.read(f.slice(0, -'.jsonl'.length)))
+      .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
+  }
+}
+
+export function formatMessages(ms: ThreadMessage[]): string {
+  const esc = (s: string) => s.replaceAll('&', '&amp;').replaceAll('<', '&lt;');
+  return ms.map((m) => `<message from="${m.from}" at="${m.at}">\n${esc(m.text)}\n</message>`).join('\n');
+}
+
+export function renderThread(t: Thread): string {
+  const pending = new Set(t.pending.map((m) => m.id));
+  const lines = [`thread ${t.id} · ${t.state} · ${t.title}`, `<task>\n${t.task}\n</task>`];
+  if (t.handoff) lines.push(`<handoff session="${t.handoff.sessionId}">\n${t.handoff.note}\n</handoff>`);
+  if (t.result !== undefined) {
+    lines.push(`<result session="${t.latest?.sessionId ?? t.sessions.at(-1)?.sessionId ?? ''}">\n${t.result}\n</result>`);
+  }
+  lines.push(`sessions: ${t.sessions.map((s) => `${s.sessionId} (${s.model}, ${s.why})`).join(', ')}`);
+  if (t.messages.length) {
+    lines.push('messages:');
+    for (const m of t.messages) {
+      lines.push(`- ${m.id} from ${m.from} at ${m.at}: ${m.text}${pending.has(m.id) ? ' (not seen yet)' : ''}`);
+    }
+  }
+  return lines.join('\n');
+}
+
+export function threadNote(t: Thread): string {
+  const lines = [
+    `This is thread ${t.id} of this project. Earlier sessions worked on the task below; the recall tool searches their logs.`,
+    `<task>\n${t.task}\n</task>`,
+  ];
+  if (t.latest?.kind === 'handoff') lines.push(`<handoff session="${t.latest.sessionId}">\n${t.latest.text}\n</handoff>`);
+  if (t.latest?.kind === 'result') lines.push(`<result session="${t.latest.sessionId}">\n${t.latest.text}\n</result>`);
+  return lines.join('\n');
+}
