@@ -0,0 +1,132 @@
+import type { SessionEvent } from '../types.ts';
+import { renderThread, type ThreadStore } from '../project/threads.ts';
+import type { ToolSpec } from './registry.ts';
+
+const MAX_HITS = 50;
+
+const escapeRegex = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
+
+export function recallTool(sources: () => { id: string; events: () => SessionEvent[] }[]): ToolSpec {
+  return {
+    name: 'recall',
+    description:
+      'Search the logs of earlier sessions of this thread (their prompts, replies, tool calls and results) for a regular expression, case-insensitive. Returns matching lines with the session and where they came from.',
+    schema: {
+      type: 'object',
+      properties: { query: { type: 'string', description: 'Regular expression to search for; plain text also works' } },
+      required: ['query'],
+      additionalProperties: false,
+    },
+    effect: 'read',
+    replay: 'safe',
+    async run(input) {
+      const query = String(input.query ?? '');
+      if (!query) return { text: 'query is required', isError: true };
+      let re: RegExp;
+      try {
+        re = new RegExp(query, 'i');
+      } catch {
+        re = new RegExp(escapeRegex(query), 'i');
+      }
+      const all = sources();
+      const n = all.length;
+      const hits: string[] = [];
+      const search = (i: number, label: string, text: string) => {
+        for (const line of text.split('\n')) {
+          if (re.test(line)) hits.push(`[session ${i} of ${n} · ${label}] ${line.trim().slice(0, 300)}`);
+        }
+      };
+      for (let i = 1; i <= n && hits.length < MAX_HITS; i++) {
+        const names = new Map<string, string>();
+        for (const e of all[i - 1]!.events()) {
+          if (hits.length >= MAX_HITS) break;
+          if (e.kind === 'tool_result') {
+            search(i, `result ${names.get(e.callId) ?? '?'}`, e.output.text);
+          } else if (e.kind === 'user') {
+            search(i, 'user', e.text);
+          } else if (e.kind === 'assistant') {
+            for (const b of e.blocks) {
+              if (b.type === 'tool_use') {
+                names.set(b.callId ?? b.id, b.name);
+                search(i, `call ${b.name}`, JSON.stringify(b.input));
+              } else if (b.type === 'text') {
+                search(i, 'assistant', b.text);
+              }
+            }
+          }
+        }
+      }
+      const shown = hits.slice(0, MAX_HITS);
+      if (!shown.length) return { text: `no match for ${query}`, isError: false };
+      const count = hits.length >= MAX_HITS ? `${MAX_HITS} or more` : `${shown.length}`;
+      return { text: `${count} match${shown.length === 1 ? '' : 'es'}\n${shown.join('\n')}`, isError: false };
+    },
+  };
+}
+
+export function threadTools(store: ThreadStore, me: string): ToolSpec[] {
+  const threads: ToolSpec = {
+    name: 'threads',
+    description: 'List the other threads in this project: id, state, title, and the latest handoff or result.',
+    schema: { type: 'object', properties: {}, additionalProperties: false },
+    effect: 'read',
+    replay: 'safe',
+    async run() {
+      const others = store.list().filter((t) => t.id !== me);
+      if (!others.length) return { text: 'no other threads in this project', isError: false };
+      const lines = others.map((t) => {
+        const head = `${t.id} [${t.state}] ${t.title}`;
+        if (!t.latest) return head;
+        return `${head}\n  ${t.latest.kind}: ${t.latest.text.replace(/\n/g, ' ').slice(0, 300)}`;
+      });
+      return { text: lines.join('\n'), isError: false };
+    },
+  };
+
+  const read: ToolSpec = {
+    name: 'read_thread',
+    description: 'Show one thread in this project: its task, handoff, result, sessions and messages.',
+    schema: {
+      type: 'object',
+      properties: { id: { type: 'string', description: 'Thread id, such as t-1a2b3c4d' } },
+      required: ['id'],
+      additionalProperties: false,
+    },
+    effect: 'read',
+    replay: 'safe',
+    async run(input) {
+      try {
+        return { text: renderThread(store.read(String(input.id ?? ''))), isError: false };
+      } catch (e) {
+        return { text: (e as Error).message, isError: true };
+      }
+    },
+  };
+
+  const send: ToolSpec = {
+    name: 'message_thread',
+    description: 'Send a message to another thread in this project. A session of that thread picks it up at its next turn boundary.',
+    schema: {
+      type: 'object',
+      properties: {
+        id: { type: 'string', description: 'Thread id to message' },
+        text: { type: 'string', description: 'The message' },
+      },
+      required: ['id', 'text'],
+      additionalProperties: false,
+    },
+    effect: 'write_workspace',
+    replay: 'unsafe',
+    async run(input) {
+      const id = String(input.id ?? '');
+      const text = String(input.text ?? '');
+      if (id === me) return { text: 'that is this thread', isError: true };
+      if (!store.has(id)) return { text: `no thread ${id}`, isError: true };
+      if (!text.trim()) return { text: 'text is required', isError: true };
+      store.send(id, me, text);
+      return { text: `sent to ${id}`, isError: false };
+    },
+  };
+
+  return [threads, read, send];
+}
