+import { describe, expect, test } from 'bun:test';
+import { mkdtempSync, readdirSync, writeFileSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { runPrompt, type RunOptions } from '../src/core/loop/run.ts';
+import { FAUX_MODEL } from '../src/core/providers/catalog.ts';
+import { fauxProvider, text, toolUse, type FauxStep } from '../src/core/providers/faux.ts';
+import { SessionLog } from '../src/core/session/log.ts';
+import { readTool } from '../src/core/tools/read.ts';
+import type { EventOf, SessionEvent } from '../src/core/types.ts';
+
+const MIN = 60_000;
+const cwd = mkdtempSync(join(tmpdir(), 'cedia-review-'));
+const BIN = join(import.meta.dir, '..', 'bin', 'cedia');
+
+function setup(steps: FauxStep[], extra: Partial<RunOptions> = {}) {
+  const log = SessionLog.create();
+  const opts: RunOptions = {
+    log,
+    provider: fauxProvider(steps),
+    model: FAUX_MODEL,
+    tools: [readTool],
+    system: 'sys',
+    cwd,
+    retry: { sleep: async () => {} },
+    ...extra,
+  };
+  return { log, opts };
+}
+
+const of = <K extends SessionEvent['kind']>(events: SessionEvent[], k: K) => events.filter((e): e is EventOf<K> => e.kind === k);
+const quota = (retryAfterMs?: number): FauxStep => ({ error: { code: 'quota', status: 429, message: 'usage limit reached', ...(retryAfterMs ? { retryAfterMs } : {}) } });
+const probe = (run: () => unknown) => ({ ...readTool, name: 'probe', run: run as typeof readTool.run });
+
+describe('tool output and thrown values', () => {
+  test('a tool that returns a plain string gives it as the result text', async () => {
+    const { log, opts } = setup([{ blocks: [toolUse('p1', 'probe', {})] }, { blocks: [text('done')] }], { tools: [probe(async () => 'hello')] });
+    await runPrompt(opts, 'go');
+    expect(of(log.events, 'tool_result')[0]).toMatchObject({ status: 'completed', output: { text: 'hello' } });
+  });
+
+  test('a tool whose text cannot be stringified still gets a string result', async () => {
+    const { log, opts } = setup([{ blocks: [toolUse('p1', 'probe', {})] }, { blocks: [text('done')] }], { tools: [probe(async () => ({ text: 10n }))] });
+    await runPrompt(opts, 'go');
+    expect(of(log.events, 'tool_result')[0]).toMatchObject({ status: 'completed', output: { text: '[object BigInt]' } });
+  });
+
+  test('a thrown value with no prototype is named, and the run goes on', async () => {
+    const { log, opts } = setup([{ blocks: [toolUse('p1', 'probe', {})] }, { blocks: [text('done')] }], { tools: [probe(async () => { throw Object.create(null); })] });
+    const r = await runPrompt(opts, 'go');
+    expect(of(log.events, 'tool_result')[0]).toMatchObject({ status: 'failed', output: { text: 'tool crashed: [object Object]' } });
+    expect(r.subtype).toBe('success');
+  });
+});
+
+describe('the quota wait ceiling', () => {
+  test('a budget shared by two runs is spent once: the second run falls back instead of waiting past it', async () => {
+    let left = 30 * MIN;
+    const shared = { quotaWaitMs: () => left, onQuotaWait: (ms: number) => void (left -= ms) };
+    const first = setup([quota(20 * MIN), { blocks: [text('ok')] }], shared);
+    expect((await runPrompt(first.opts, 'a')).subtype).toBe('success');
+    expect(left).toBe(10 * MIN);
+    const second = setup([quota(20 * MIN), { blocks: [text('unreachable')] }], shared);
+    expect((await runPrompt(second.opts, 'b')).subtype).toBe('error_during_execution');
+    expect(left).toBe(10 * MIN);
+  });
+
+  test('a retry-after exactly at the ceiling is waited', async () => {
+    const { opts } = setup([quota(20 * MIN), { blocks: [text('ok')] }], { quotaWaitMs: 20 * MIN });
+    expect((await runPrompt(opts, 'a')).subtype).toBe('success');
+  });
+});
+
+// A refused history followed by a spent quota: the quota falls back on the session the refusal restarted.
+describe('a refused history, then a spent quota', () => {
+  test('the run goes on on the fallback model in a third session', () => {
+    const dir = mkdtempSync(join(tmpdir(), 'cedia-refused-'));
+    const home = join(dir, 'home');
+    const script = [
+      { blocks: [{ type: 'tool_use', id: 'c1', name: 'bash', input: { command: 'echo good > f.txt' } }] },
+      { error: { code: 'bad_request', status: 400, message: 'Invalid `signature` in `thinking` block' } },
+      { error: { code: 'quota', status: 402, message: 'Insufficient Balance' } },
+      { blocks: [{ type: 'tool_use', id: 'c2', name: 'bash', input: { command: 'grep -q good f.txt' } }] },
+      { blocks: [text('done')] },
+    ];
+    const scriptPath = join(dir, 'script.json');
+    writeFileSync(scriptPath, JSON.stringify(script));
+    const args = ['-p', 'make f.txt say good', '--output-format', 'json', '--permission', 'workspace', '--sandbox', 'off', '--check', 'grep -q good f.txt', '--fallback', 'faux/fallback'];
+    const proc = Bun.spawnSync([BIN, '-m', 'faux', '--cwd', dir, ...args], { env: { ...process.env, CEDIA_FAUX_SCRIPT: scriptPath, CEDIA_HOME: home } });
+    const [project] = readdirSync(join(home, 'sessions'));
+    const files = readdirSync(join(home, 'sessions', project!));
+    expect(files).toHaveLength(3);
+    expect(JSON.parse(proc.stdout.toString())).toMatchObject({ subtype: 'success' });
+  });
+});

