+import { describe, expect, test } from 'bun:test';
+import { mkdtempSync, writeFileSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { runPrompt, type RunOptions } from '../src/core/loop/run.ts';
+import { buildMessages } from '../src/core/context/build.ts';
+import { FAUX_MODEL } from '../src/core/providers/catalog.ts';
+import { fauxProvider, text, toolUse, type FauxStep } from '../src/core/providers/faux.ts';
+import { SessionLog } from '../src/core/session/log.ts';
+import { bashTool } from '../src/core/tools/bash.ts';
+import { readTool } from '../src/core/tools/read.ts';
+import type { EventOf, SessionEvent } from '../src/core/types.ts';
+
+const cwd = mkdtempSync(join(tmpdir(), 'cedia-loop-review-'));
+writeFileSync(join(cwd, 'a.txt'), 'alpha\n');
+
+function setup(steps: FauxStep[], extra: Partial<RunOptions> = {}) {
+  const log = SessionLog.create();
+  const sleeps: number[] = [];
+  const opts: RunOptions = {
+    log,
+    provider: fauxProvider(steps),
+    model: FAUX_MODEL,
+    tools: [readTool, bashTool],
+    system: 'sys',
+    cwd,
+    retry: { sleep: async (ms) => void sleeps.push(ms) },
+    ...extra,
+  };
+  return { log, opts, sleeps };
+}
+
+const of = <K extends SessionEvent['kind']>(events: SessionEvent[], k: K) => events.filter((e): e is EventOf<K> => e.kind === k);
+const MIN = 60_000;
+const spent = (retryAfterMs?: number, status = 429): FauxStep => ({
+  error: { code: 'quota', status, message: 'usage limit reached', ...(retryAfterMs !== undefined ? { retryAfterMs } : {}) },
+});
+
+describe('quota waits', () => {
+  test('a zero retry-after is not waited on: the session ends at once, with one attempt', async () => {
+    const { log, opts, sleeps } = setup([spent(0), { blocks: [text('ok')] }], { quotaWaitMs: 30 * MIN });
+    expect((await runPrompt(opts, 'hi')).subtype).toBe('error_during_execution');
+    expect(of(log.events, 'attempt')).toHaveLength(1);
+    expect(sleeps).toEqual([]);
+  });
+
+  test('a 402 with a retry-after is a spent balance, not a wait', async () => {
+    const { log, opts, sleeps } = setup([{ error: { code: 'quota', status: 402, message: 'Insufficient Balance', retryAfterMs: 20 * MIN } }, { blocks: [text('ok')] }], { quotaWaitMs: 30 * MIN });
+    expect((await runPrompt(opts, 'hi')).subtype).toBe('error_during_execution');
+    expect(of(log.events, 'attempt')).toHaveLength(1);
+    expect(sleeps).toEqual([]);
+  });
+
+  test('quota waits do not use up the retries for other errors', async () => {
+    const server: FauxStep = { error: { code: 'server', status: 500, message: 'x' } };
+    const { opts } = setup([spent(1000), spent(1000), spent(1000), spent(1000), server, { blocks: [text('ok')] }], { quotaWaitMs: 10 * MIN });
+    expect(await runPrompt(opts, 'hi')).toMatchObject({ subtype: 'success', result: 'ok' });
+  });
+});
+
+describe('malformed history', () => {
+  test('a tool_use id that repeats is sent back once, as the run kept it', () => {
+    const events: SessionEvent[] = [
+      { kind: 'assistant', wire: 'faux', model: FAUX_MODEL.ref, blocks: [toolUse('dup', 'bash', {}), toolUse('dup', 'bash', { command: 'x' })], stop: 'tool_use', usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 } } as never,
+    ];
+    const messages = buildMessages(events);
+    expect(messages).toHaveLength(1);
+    expect(messages[0]!.role === 'assistant' && messages[0]!.blocks.length).toBe(1);
+  });
+});
+
+describe('tool output that JSON cannot hold', () => {
+  const odd = (name: string, run: () => Promise<unknown>) => ({ name, description: name, schema: { type: 'object' }, effect: 'read' as const, replay: 'safe' as const, run: run as never });
+
+  test('BigInt, circular and function values still get a string result', async () => {
+    const circular: Record<string, unknown> = {};
+    circular.self = circular;
+    const tools = [
+      odd('big', async () => ({ text: 12n, isError: false })),
+      odd('loop', async () => ({ text: circular, isError: false })),
+      odd('fn', async () => ({ text: () => 1, isError: false })),
+    ];
+    const { log, opts } = setup([{ blocks: [toolUse('c1', 'big', {}), toolUse('c2', 'loop', {}), toolUse('c3', 'fn', {})] }, { blocks: [text('ok')] }], { tools });
+    expect((await runPrompt(opts, 'go')).subtype).toBe('success');
+    const results = of(log.events, 'tool_result');
+    expect(results.map((r) => [r.status, typeof r.output.text])).toEqual([
+      ['completed', 'string'],
+      ['completed', 'string'],
+      ['completed', 'string'],
+    ]);
+    expect(results[0]!.output.text).toBe('12');
+    expect(results[1]!.output.text).toBe('[object Object]');
+  });
+});

