+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('10 units of one sku get 5% off', () => {
+    // 10 pens = 1200, 5% off = 60, subtotal 1140; shipping 800; tax 7% of 1940 = 135.8 -> 136
+    expect(totals(cart('US', [['PEN', 10]]))).toMatchObject({ subtotal: 1140, shipping: 800, tax: 136, total: 2076 });
+  });
+
+  test('50 units of one sku get 10% off, not 5%', () => {
+    // 50 pens = 6000, 10% off = 600, subtotal 5400 >= 5000 ships free; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('lines of the same sku count together for bulk discounts', () => {
+    // 5 + 5 pens are 10 units: 5% off the 1200 total, same as one line of 10
+    const t = totals(cart('US', [['PEN', 5], ['PEN', 5]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t.lines[0]).toMatchObject({ quantity: 10, discount: 60 });
+    expect(t.total).toBe(2076);
+  });
+
+  test('UK ships free from 4000', () => {
+    // 2 bags = 4400 >= 4000; tax 20% of 4400 = 880
+    expect(totals(cart('UK', [['BAG', 2]]))).toMatchObject({ subtotal: 4400, shipping: 0, tax: 880, total: 5280 });
+  });
+
+  test('shipping threshold uses the discounted subtotal', () => {
+    // bags 4400 + pens 720 (6 units, no bulk) = 5120; FLAT5 -500 = 4620 discounted.
+    // US threshold is 5000, so shipping is charged; tax 7% of 5420 = 379.4 -> 379
+    expect(totals(cart('US', [['BAG', 2], ['PEN', 6]], 'FLAT5'))).toMatchObject({ subtotal: 5120, coupon: 500, shipping: 800, tax: 379, total: 5799 });
+  });
+});

