+import { expect, test } from 'bun:test';
+import { formatDuration, parseDuration } from '../src/duration.ts';
+
+test('parseDuration accepts the documented forms', () => {
+  expect(parseDuration('90s')).toBe(90_000);
+  expect(parseDuration('1h30m')).toBe(5_400_000);
+  expect(parseDuration('1h 30m')).toBe(5_400_000);
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('2d 4h')).toBe(187_200_000);
+  expect(parseDuration('  2d 4h  ')).toBe(187_200_000);
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('0.0005s')).toBe(1);
+});
+
+test('parseDuration throws on invalid input and includes the input', () => {
+  for (const input of ['', '10', '5x', 'h', '-1s', '1..5h', '.5h', '1h-', '1 h', '1hh']) {
+    expect(() => parseDuration(input)).toThrow(`${JSON.stringify(input)}`);
+  }
+});
+
+test('formatDuration', () => {
+  expect(formatDuration(5_400_000)).toBe('1h30m');
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(90_061_001)).toBe('1d1h1m1s1ms');
+});
+
+test('formatDuration throws on negative, NaN and Infinity', () => {
+  expect(() => formatDuration(-1)).toThrow();
+  expect(() => formatDuration(NaN)).toThrow();
+  expect(() => formatDuration(Infinity)).toThrow();
+});
+
+test('error message contains the raw input, even with quotes, backslashes or newlines', () => {
+  for (const input of ['5"x', 'a\\b', '1h\n2x']) {
+    expect(() => parseDuration(input)).toThrow(input);
+  }
+});
+
+test('formatDuration rounds fractional milliseconds', () => {
+  expect(formatDuration(1.6)).toBe('2ms');
+  expect(formatDuration(0.4)).toBe('0s');
+});
diff -ruN --exclude=node_modules --exclude=.git a/test/lru.rules.test.ts b/test/lru.rules.test.ts
--- a/test/lru.rules.test.ts	1970-01-01 07:00:00
+++ b/test/lru.rules.test.ts	2026-10-24 03:15:56
@@ -0,0 +1,100 @@
+import { expect, test } from 'bun:test';
+import { LRU } from '../src/lru.ts';
+
+function recorder<K, V>(cache: LRU<K, V>) {
+  const events: [K, V, string][] = [];
+  cache.onEvict = (key, value, reason) => events.push([key, value, reason]);
+  return events;
+}
+
+test('get hit makes an entry most recent', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 1000, () => t);
+  const events = recorder(cache);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1);
+  cache.set('c', 3);
+  expect(events).toEqual([['b', 2, 'capacity']]);
+  expect(cache.keys()).toEqual(['c', 'a']);
+});
+
+test('expiry happens at exactly t + ttl', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(5, 1000, () => t);
+  const events = recorder(cache);
+  cache.set('a', 1);
+  t = 999;
+  expect(cache.get('a')).toBe(1);
+  t = 1000;
+  expect(cache.get('a')).toBeUndefined();
+  expect(events).toEqual([['a', 1, 'expired']]);
+});
+
+test('set over capacity removes expired entries first and keeps live ones', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  const events = recorder(cache);
+  cache.set('old', 1);
+  t = 60;
+  cache.set('live', 2);
+  t = 100;
+  cache.set('new', 3);
+  expect(events).toEqual([['old', 1, 'expired']]);
+  expect(cache.keys()).toEqual(['new', 'live']);
+});
+
+test('re-setting an existing key refreshes its ttl and causes no eviction', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  const events = recorder(cache);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  t = 90;
+  cache.set('a', 10);
+  expect(events).toEqual([]);
+  t = 150;
+  expect(cache.get('a')).toBe(10);
+  expect(cache.get('b')).toBeUndefined();
+  expect(events).toEqual([['b', 2, 'expired']]);
+});
+
+test('delete reports live, expired and missing entries', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(5, 100, () => t);
+  const events = recorder(cache);
+  cache.set('live', 1);
+  cache.set('stale', 2);
+  expect(cache.delete('live')).toBe(true);
+  expect(events).toEqual([['live', 1, 'delete']]);
+  t = 100;
+  expect(cache.delete('stale')).toBe(false);
+  expect(events[1]).toEqual(['stale', 2, 'expired']);
+  events.length = 0;
+  expect(cache.delete('missing')).toBe(false);
+  expect(events).toEqual([]);
+});
+
+test('size and keys exclude expired entries without mutating', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(5, 100, () => t);
+  const events = recorder(cache);
+  cache.set('a', 1);
+  t = 50;
+  cache.set('b', 2);
+  t = 120;
+  expect(cache.size).toBe(1);
+  expect(cache.keys()).toEqual(['b']);
+  expect(events).toEqual([]);
+  expect(cache.size).toBe(1);
+});
+
+test('get hit does not refresh the ttl', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.set('a', 1);
+  t = 50;
+  expect(cache.get('a')).toBe(1);
+  t = 100;
+  expect(cache.get('a')).toBeUndefined();
+});
