+import { expect, test } from 'bun:test';
+import { slugify, uniqueSlug } from '../src/slug.ts';
+
+test('diacritics are dropped', () => {
+  expect(slugify('àçñź')).toBe('acnz');
+});
+
+test('special letters', () => {
+  expect(slugify('Straße')).toBe('strasse');
+  expect(slugify('Æble Œuvre')).toBe('aeble-oeuvre');
+  expect(slugify('Øl Łódź Đak')).toBe('ol-lodz-dak');
+});
+
+test('separators and superscripts', () => {
+  expect(slugify('--Hello___World--')).toBe('hello-world');
+  expect(slugify('x²')).toBe('x');
+});
+
+test('max cuts at a dash or at max', () => {
+  expect(slugify('ab-cd-ef', 5)).toBe('ab-cd');
+  expect(slugify('ab-cd-ef', 4)).toBe('ab');
+  expect(slugify('abcdefgh', 3)).toBe('abc');
+  expect(slugify('ab-cd', 10)).toBe('ab-cd');
+});
+
+test('uniqueSlug', () => {
+  expect(uniqueSlug('post', new Set())).toBe('post');
+  expect(uniqueSlug('post', new Set(['post', 'post-2']))).toBe('post-3');
+});
+
+test('input made only of separators gives an empty slug', () => {
+  expect(slugify('---')).toBe('');
+});
+
+test('cut at a dash at position max-1', () => {
+  expect(slugify('abcd-ef', 5)).toBe('abcd');
+});
+
+test('precomposed letters on top of ø, æ and œ', () => {
+  expect(slugify('ǿl')).toBe('ol');
+  expect(slugify('ǣ')).toBe('ae');
+  expect(slugify('ǿ')).toBe('o');
+});
